/**
 * Link version 1, frozen: the voting, boost and turbo channels.
 *
 * Written out as concrete types, copied from the shapes the app resolved when link version 1 was cut. It never
 * references the living types, so a change to a handler cannot move it. Do not edit this file to match a changed
 * handler: a change that breaks it needs a new LINK_VERSION and a new `contract/v<N>/` (see protocol.ts for the
 * rule). `tests/remote/contractV1.test.ts` checks the living types against it.
 */

import type { ActiveChallengesResponseV1, ChallengeV1 } from './shapesChallenges';

export type VotingChannelsV1 = {
    'apply-boost-to-entry': {
        args: [challengeId: string | number, imageId: string];
        result:
            | { success: false; error: string }
            | { success: false; error: 'invalid-args' }
            | { success: true; message: string };
    };
    'apply-turbo-to-entry': {
        args: [challengeId: string | number, imageId: string];
        result:
            | { success: false; error: string }
            | { success: false; error: 'invalid-args' }
            | { success: true; message: string };
    };
    'fill-challenge-now': {
        args: [challengeId: string | number, mode: 'all' | 'one'];
        result:
            | { success: false; error: string }
            | { success: false; error: 'invalid-args' }
            | { success: false; error: 'challenge-data-incomplete' }
            | { success: false; error: 'Challenge no longer active' }
            | {
                  success: boolean;
                  submitted: number;
                  skipped: number;
                  error: undefined | string;
                  message: undefined | string;
              };
    };
    'get-active-challenges': { args: []; result: ActiveChallengesResponseV1 };
    'get-deadline-actions': {
        args: [challenge: ChallengeV1];
        result:
            | {
                  success: false;
                  error: string;
                  actions?: undefined;
                  boostBlocked?: undefined;
                  turboBlocked?: undefined;
                  boostBlockedBy?: undefined;
                  turboBlockedBy?: undefined;
                  boostReleaseAt?: undefined;
                  turboReleaseAt?: undefined;
                  boostPinSubmits?: undefined;
              }
            | {
                  success: true;
                  actions: { action: string; thresholdSec: number; dueAt: null | number }[];
                  boostBlocked: boolean;
                  turboBlocked: boolean;
                  boostBlockedBy: null | 'pin' | 'flag';
                  turboBlockedBy: null | 'pin' | 'flag';
                  boostReleaseAt: null | number;
                  turboReleaseAt: null | number;
                  boostPinSubmits: boolean;
                  error?: undefined;
              };
    };
    'gui-vote': {
        args: [];
        result:
            | { success: false; error: string }
            | { success: boolean; error: undefined | string; data?: undefined }
            | { success: boolean; data: string; error?: undefined };
    };
    'play-auto-turbo': {
        args: [challengeId: string | number, challengeTitle: string];
        result:
            | { success: false; error: string }
            | { success: false; error: 'invalid-args' }
            | { success: false; error: 'challenge-data-incomplete' }
            | { success: false; error: 'Challenge no longer active' }
            | {
                  success: true;
                  result:
                      | null
                      | {
                            kind: 'snap';
                            answered: number;
                            total: number;
                            meanAgreement: null | number;
                            won: boolean;
                            stopReason:
                                | 'completed'
                                | 'no-model'
                                | 'unparsed-caption'
                                | 'judge-failed'
                                | 'unavailable'
                                | 'withdrawn'
                                | 'request-failed'
                                | 'vote-unclear'
                                | 'cancelled';
                            played?: undefined;
                            correct?: undefined;
                            flipped?: undefined;
                            doubleFailed?: undefined;
                        }
                      | {
                            kind: 'classic';
                            played: number;
                            correct: number;
                            flipped: number;
                            doubleFailed: number;
                            won: boolean;
                            answered?: undefined;
                            total?: undefined;
                            meanAgreement?: undefined;
                            stopReason?: undefined;
                        };
                  error?: undefined;
              };
    };
    'refresh-api': { args: []; result: { success: false; error: string } | { success: true } };
    'run-voting-cycle-for-challenge': {
        args: [challengeId: string | number];
        result:
            | { success: false; error: string }
            | { success: boolean; error: undefined | string; message?: undefined; challenges?: undefined }
            | { success: boolean; message: string; challenges: undefined | ChallengeV1[]; error?: undefined }
            | { success: boolean; error: string; challenges: undefined | ChallengeV1[]; message?: undefined };
    };
    'should-cancel-voting': { args: []; result: boolean };
    'vote-all-challenges-manual': {
        args: [];
        result:
            | { success: false; error: string }
            | { success: true; message: string; stats: { total: number; voted: number; skipped: number } };
    };
    'vote-on-challenge': {
        args: [challengeId: string | number, challengeTitle: string];
        result:
            | { success: false; error: string }
            | { success: false; error: undefined | string; message?: undefined }
            | { success: true; message: string; error?: undefined };
    };
    'vote-on-challenge-manual': {
        args: [challengeId: string | number, challengeTitle: string];
        result:
            | { success: false; error: string }
            | { success: false; error: undefined | string; message?: undefined }
            | { success: true; message: string; error?: undefined };
    };
};
